"use client";

import * as React from "react";
import { HugeiconsIcon } from "@hugeicons/react";
import { Field, FieldDescription, FieldLabel } from "@/components/ui/field";
import {
  ColorPicker,
  ColorPickerAlpha,
  ColorPickerEyeDropper,
  ColorPickerFormat,
  ColorPickerHue,
  ColorPickerSelection,
} from "@/components/ui/color-picker";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { RangeSlider } from "@/components/motion/range-slider";
import { cn } from "@/lib/utils";

export type ToggleOption = {
  value: string;
  label: string;
  icon?: React.ComponentProps<typeof HugeiconsIcon>["icon"];
};

/**
 * Compact segmented control: a recessed track with the selected option raised
 * out of it, matching the viewport toggle in the editor header. Rendered as
 * plain buttons rather than shadcn ToggleGroup, whose baked-in rounded-3xl /
 * rounded-4xl rules fight the square look this panel wants.
 *
 * Icon-only whenever an option supplies an icon; the label still rides along
 * as the title and aria-label so hover and screen readers keep the words.
 */
export function OptionToggle({
  value,
  onChange,
  options,
  ariaLabel,
  className,
}: {
  value: string;
  onChange: (value: string) => void;
  options: ToggleOption[];
  ariaLabel?: string;
  className?: string;
}) {
  return (
    <div
      role="group"
      data-slot="option-toggle"
      aria-label={ariaLabel}
      className={cn(
        // max-w-fit, not just w-fit: shadcn Field is vertical by default,
        // which sets *:w-full on every direct child and would otherwise
        // stretch this track across the panel. A max-width still wins against
        // that width:100% without needing !important.
        "inline-flex h-7 w-fit max-w-fit self-start items-center rounded-md bg-muted p-0.5",
        className
      )}
    >
      {options.map((option, index) => {
        const selected = option.value === value;
        return (
          <React.Fragment key={option.value}>
            {index > 0 && (
              <span
                aria-hidden
                className="mx-px h-3.5 w-px shrink-0 bg-border/70"
              />
            )}
            <button
              type="button"
              onClick={() => onChange(option.value)}
              aria-pressed={selected}
              aria-label={option.label}
              title={option.label}
              className={cn(
                // Sized to its contents, not stretched: a square cell for an
                // icon, just enough padding for a word.
                "flex h-6 min-w-6 shrink-0 items-center justify-center rounded-[5px] px-1.5 text-[11px] font-medium transition-colors outline-none focus-visible:ring-2 focus-visible:ring-ring/50",
                selected
                  ? "bg-card text-foreground shadow-xs"
                  : "text-muted-foreground hover:text-foreground"
              )}
            >
              {option.icon ? (
                <HugeiconsIcon
                  icon={option.icon}
                  strokeWidth={2}
                  data-icon="icon"
                  className="size-3.5"
                />
              ) : (
                option.label
              )}
            </button>
          </React.Fragment>
        );
      })}
    </div>
  );
}

/**
 * Stacked label + value readout above the motion RangeSlider. Shared by the
 * block inspector and the theme panel so every slider looks the same.
 */
export function SliderField({
  label,
  value,
  min,
  max,
  step = 1,
  suffix = "",
  description,
  onChange,
}: {
  label: string;
  value: number;
  min: number;
  max: number;
  step?: number;
  suffix?: string;
  description?: string;
  onChange: (v: number) => void;
}) {
  return (
    <Field>
      <div className="flex items-center justify-between gap-2">
        <FieldLabel>{label}</FieldLabel>
        <span className="text-[11px] tabular-nums text-muted-foreground">
          {value}
          {suffix}
        </span>
      </div>
      <RangeSlider
        value={value}
        min={min}
        max={max}
        step={step}
        onValueChange={onChange}
        aria-label={label}
        className="h-7 rounded-md"
      />
      {description && <FieldDescription>{description}</FieldDescription>}
    </Field>
  );
}

/**
 * One flat, always-visible group in the inspector: a small title row with
 * optional icon-only actions on the right, a rule beneath it, and the fields
 * below. Replaces the accordion the inspector used to be, so every control is
 * visible at once instead of one section at a time.
 */
export function InspectorSection({
  title,
  actions,
  className,
  children,
}: {
  title: string;
  actions?: React.ReactNode;
  className?: string;
  children: React.ReactNode;
}) {
  return (
    <section
      className={cn(
        "border-b border-border/60 px-3 py-2.5 last:border-b-0",
        // Density scope. The shadcn field primitives are sized for forms
        // (FieldGroup alone is gap-7), which is far too airy for an inspector
        // panel, so the section tightens every slot it contains in one place
        // instead of every call site overriding them by hand.
        // Two columns. A field holding nothing but a segmented control is
        // narrow enough to pair up, so it takes one column; anything else — a
        // slider, a colour row, a text input — spans both. Driven off the
        // markup rather than every call site opting in by hand.
        "[&_[data-slot=field-group]]:grid [&_[data-slot=field-group]]:grid-cols-2 [&_[data-slot=field-group]]:items-start [&_[data-slot=field-group]]:gap-x-2 [&_[data-slot=field-group]]:gap-y-2.5",
        "[&_[data-slot=field]]:col-span-2 [&_[data-slot=field]:has(>[data-slot=option-toggle])]:col-span-1",
        "[&_[data-slot=field]]:gap-1",
        "[&_[data-slot=field-label]]:text-[11px] [&_[data-slot=field-label]]:font-medium [&_[data-slot=field-label]]:text-muted-foreground",
        "[&_[data-slot=field-description]]:text-[11px] [&_[data-slot=field-description]]:leading-snug",
        "[&_[data-slot=input]]:h-7 [&_[data-slot=input]]:text-xs",
        className
      )}
    >
      <div className="mb-2 flex h-5 items-center justify-between gap-2">
        <h3 className="text-[11px] font-semibold tracking-tight text-foreground">
          {title}
        </h3>
        {actions && (
          <div className="flex items-center gap-0.5 text-muted-foreground">
            {actions}
          </div>
        )}
      </div>
      {children}
    </section>
  );
}

/**
 * Turns the picker's [r, g, b, a] back into the hex string the document stores.
 *
 * Alpha only appears when it is actually below 1, so fully opaque colours stay
 * as plain 6-digit hex and nothing downstream sees a format it did not before.
 * A translucent colour becomes 8-digit #RRGGBBAA, which the compiler writes
 * into inline CSS as-is.
 */
function rgbaToHex(r: number, g: number, b: number, a: number) {
  const channels = [r, g, b];
  if (a < 1) channels.push(a * 255);
  return (
    "#" +
    channels
      .map((channel) => Math.round(channel).toString(16).padStart(2, "0"))
      .join("")
  );
}

/**
 * A colour as one control rather than a swatch sitting next to a text box:
 * swatch, hex, then an optional opacity cell behind a divider.
 *
 * The swatch opens the full picker — area, hue, eyedropper, format readout —
 * in a popover rather than handing off to the OS colour dialog, and that
 * popover is also where "transparent" lives, since an unset colour is a real
 * state here rather than an empty text field. The hex cell always shows a hex,
 * falling back to the colour this would inherit, so the row never reads blank.
 */
export function ColorField({
  value,
  onChange,
  fallback = "#ffffff",
  trailing,
  opacity,
  onOpacityChange,
  allowTransparent = true,
  className,
}: {
  value?: string;
  onChange: (value: string | undefined) => void;
  /** Shown when nothing is set — the colour this would inherit. */
  fallback?: string;
  trailing?: React.ReactNode;
  /** Percent 0-100. Renders the opacity cell only when both are given. */
  opacity?: number;
  onOpacityChange?: (value: number) => void;
  /** Offer "Transparent" in the picker. Off for colours that must be set. */
  allowTransparent?: boolean;
  className?: string;
}) {
  const [pickerOpen, setPickerOpen] = React.useState(false);
  const isTransparent = !value;

  // Opacity is read straight out of the stored colour: an 8-digit #RRGGBBAA
  // carries it, anything shorter is fully opaque. That means every colour row
  // shows the percentage without the document needing a parallel field. A
  // caller with its own opacity number (the shadow) overrides both halves.
  const alphaFromValue = React.useMemo(() => {
    if (!value) return 0;
    const match = /^#?[0-9a-f]{6}([0-9a-f]{2})$/i.exec(value);
    if (!match) return 100;
    return Math.round((parseInt(match[1], 16) / 255) * 100);
  }, [value]);

  const shownOpacity = opacity ?? alphaFromValue;
  const applyOpacity =
    onOpacityChange ??
    ((next: number) => {
      const base = (value || fallback).slice(0, 7);
      if (next >= 100) return onChange(base);
      const suffix = Math.round((next / 100) * 255)
        .toString(16)
        .padStart(2, "0");
      onChange(base + suffix);
    });

  return (
    <div
      className={cn(
        // Hugs its contents like the segmented control. max-w-fit is what
        // actually wins here: shadcn Field sets *:w-full on its children.
        "inline-flex h-7 w-fit max-w-fit self-start items-center gap-1.5 rounded-md border border-input bg-transparent pl-1 dark:bg-input/30",
        "focus-within:border-ring focus-within:ring-[3px] focus-within:ring-ring/50",
        className
      )}
    >
      <Popover open={pickerOpen} onOpenChange={setPickerOpen}>
        <PopoverTrigger
          type="button"
          aria-label="Edit colour"
          className="flex size-5 shrink-0 items-center justify-center rounded-[3px] outline-none focus-visible:ring-2 focus-visible:ring-ring/50"
        >
          <span
            className="size-4 rounded-[3px] border border-border/60"
            style={
              isTransparent
                ? {
                    // Diagonal strike: the conventional "no colour" swatch.
                    backgroundImage:
                      "linear-gradient(to top right, transparent calc(50% - 1px), var(--destructive) calc(50% - 1px), var(--destructive) calc(50% + 1px), transparent calc(50% + 1px))",
                  }
                : { backgroundColor: value }
            }
          />
        </PopoverTrigger>
        <PopoverContent align="start" className="w-60 p-3">
          <ColorPicker
            // ColorPicker seeds its sliders once, on mount. Keying it to the
            // colour we opened with means each open starts from what is
            // actually stored, rather than from whatever the last session of
            // the picker left behind.
            key={value ?? "transparent"}
            // Transparent opens at zero alpha rather than at a fully opaque
            // fallback, so the alpha slider reflects what the swatch shows.
            // Dragging it up is then the natural way back to a real colour.
            defaultValue={value || fallback.slice(0, 7) + "00"}
            onChange={([r, g, b, a]) => {
              // Dragging alpha to zero is the same statement as "Transparent",
              // so it clears rather than storing an invisible colour — but only
              // where unset is a legal state.
              if (a === 0 && allowTransparent) return onChange(undefined);
              onChange(rgbaToHex(r, g, b, a));
            }}
            className="h-auto w-full gap-3"
          >
            <ColorPickerSelection className="h-32 rounded-md" />
            <ColorPickerHue />
            <ColorPickerAlpha />
            <div className="flex items-center gap-2">
              <ColorPickerEyeDropper className="size-8" />
              <ColorPickerFormat />
            </div>
          </ColorPicker>
          {allowTransparent && (
            <button
              type="button"
              onClick={() => {
                onChange(undefined);
                // Close as well: leaving the picker open on the colour that was
                // just cleared reads as "nothing happened".
                setPickerOpen(false);
              }}
              className={cn(
                "mt-3 flex h-7 w-full items-center justify-center rounded-md border text-[11px] font-medium transition-colors",
                isTransparent
                  ? "border-ring bg-accent text-foreground"
                  : "border-input text-muted-foreground hover:text-foreground"
              )}
            >
              Transparent
            </button>
          )}
        </PopoverContent>
      </Popover>
      <input
        value={(value || fallback).toUpperCase()}
        onChange={(event) => onChange(event.target.value || undefined)}
        spellCheck={false}
        aria-label="Hex colour"
        className={cn(
          "w-[9ch] shrink-0 bg-transparent font-mono text-[11px] uppercase outline-none",
          isTransparent ? "text-muted-foreground" : "text-foreground"
        )}
      />
      <span aria-hidden className="h-full w-px shrink-0 bg-border/70" />
      <span className="flex shrink-0 items-center pr-1.5 text-[11px] text-muted-foreground">
        <input
          type="number"
          min={0}
          max={100}
          value={shownOpacity}
          aria-label="Opacity"
          onChange={(event) => {
            const next = Number(event.target.value);
            if (Number.isNaN(next)) return;
            applyOpacity(Math.min(100, Math.max(0, next)));
          }}
          className="w-[4ch] bg-transparent text-right tabular-nums text-foreground outline-none [appearance:textfield] [&::-webkit-inner-spin-button]:appearance-none"
        />
        <span className="pl-1">%</span>
      </span>
      {trailing && (
        <>
          <span aria-hidden className="h-full w-px shrink-0 bg-border/70" />
          <span className="flex shrink-0 items-center gap-1 pr-1.5 text-[11px] text-muted-foreground">
            {trailing}
          </span>
        </>
      )}
    </div>
  );
}

"use client";

import { Input } from "@/components/ui/input";

type ImageUploadInputProps = {
  id?: string;
  value: string;
  placeholder?: string;
  onChange: (url: string) => void;
};

/**
 * Image field — URL only.
 *
 * The editor deliberately ships no storage provider. Uploading means picking
 * one (UploadThing, S3, Cloudinary, a route handler of your own), and a
 * component library should not make that choice for the host app. A button
 * that produced a `data:` URL instead would be worse than none: it inlines
 * megabytes of base64 into an email that most clients then refuse to render.
 *
 * To add uploading, wrap this field: keep the URL input, add your own button,
 * and call `onChange` with the URL your storage returns.
 */
export function ImageUploadInput({
  id,
  value,
  placeholder,
  onChange,
}: ImageUploadInputProps) {
  return (
    <Input
      id={id}
      type="url"
      value={value}
      placeholder={placeholder ?? "https://..."}
      onChange={(event) => onChange(event.target.value)}
    />
  );
}

"use client";

import { ArrowDownIcon, ArrowUpIcon, PlusIcon, XIcon } from "lucide-react";

import { Button } from "@/components/ui/button";
import { Field, FieldDescription, FieldLabel, FieldTitle } from "@/components/ui/field";
import { Input } from "@/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { createId, type SocialLink } from "@/lib/email/document";
import {
  SOCIAL_PLATFORMS,
  socialIconSrc,
  socialPlatform,
  type SocialPlatform,
} from "@/lib/email/social";
import { cn } from "@/lib/utils";
import { ImageUploadInput } from "./image-upload-input";

/**
 * The social block's link list: pick a platform, paste a URL, add and remove
 * rows freely.
 *
 * This replaced three hard-coded rows (Facebook / Twitter / Instagram) that
 * could take a URL but could not be changed, added to, or removed — which
 * meant every sender shipped the same three icons whether or not they used
 * those networks.
 *
 * Lives in its own file because block-inspector.tsx is already well past the
 * size where another few hundred lines belong in it.
 */

/** A 20px version of the same PNG the canvas and the email use, so the
 *  picker can never show an icon the email won't. */
function PlatformIcon({ id, className }: { id: SocialPlatform; className?: string }) {
  return (
    // eslint-disable-next-line @next/next/no-img-element -- 20px static asset
    <img
      src={`/social/${id}.png`}
      alt=""
      aria-hidden
      className={cn("size-5 shrink-0 rounded-full", className)}
    />
  );
}

export function SocialLinksField({
  links,
  onChange,
}: {
  links: SocialLink[];
  onChange: (links: SocialLink[]) => void;
}) {
  function update(id: string, patch: Partial<SocialLink>) {
    onChange(links.map((l) => (l.id === id ? { ...l, ...patch } : l)));
  }

  function move(index: number, delta: number) {
    const next = [...links];
    const target = index + delta;
    if (target < 0 || target >= next.length) return;
    [next[index], next[target]] = [next[target], next[index]];
    onChange(next);
  }

  function add() {
    // Offer the first platform they aren't already using, so adding four in a
    // row doesn't produce four Instagrams to fix by hand.
    const used = new Set(links.map((l) => l.platform));
    const next =
      SOCIAL_PLATFORMS.find((p) => p.id !== "custom" && !used.has(p.id))?.id ?? "custom";
    onChange([...links, { id: createId(), platform: next, url: "" }]);
  }

  return (
    <>
      <Field>
        <FieldTitle>Social links</FieldTitle>
        <FieldDescription>
          Links without a URL are hidden from the sent email.
        </FieldDescription>
      </Field>

      {links.map((link, index) => {
        const spec = socialPlatform(link.platform);
        const isCustom = link.platform === "custom";

        return (
          <div key={link.id} className="rounded-lg border border-border/60 p-2.5">
            <div className="flex items-center gap-1.5">
              <Select
                value={link.platform}
                onValueChange={(platform) =>
                  // Dropping iconSrc/label on the way out of `custom` keeps a
                  // stale uploaded icon from silently overriding a real brand
                  // one if they switch back and forth.
                  update(link.id, {
                    platform: platform as SocialPlatform,
                    ...(platform === "custom" ? {} : { iconSrc: undefined, label: undefined }),
                  })
                }
              >
                <SelectTrigger className="h-8 flex-1 text-xs">
                  <SelectValue>
                    <span className="flex items-center gap-2">
                      <PlatformIcon id={spec.id} />
                      <span className="truncate">{spec.label}</span>
                    </span>
                  </SelectValue>
                </SelectTrigger>
                <SelectContent>
                  {SOCIAL_PLATFORMS.map((p) => (
                    <SelectItem key={p.id} value={p.id} className="text-xs">
                      <span className="flex items-center gap-2">
                        <PlatformIcon id={p.id} />
                        {p.label}
                      </span>
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>

              <Button
                variant="ghost" size="icon" className="size-7 shrink-0"
                aria-label="Move up" disabled={index === 0}
                onClick={() => move(index, -1)}
              >
                <ArrowUpIcon className="size-3.5" />
              </Button>
              <Button
                variant="ghost" size="icon" className="size-7 shrink-0"
                aria-label="Move down" disabled={index === links.length - 1}
                onClick={() => move(index, 1)}
              >
                <ArrowDownIcon className="size-3.5" />
              </Button>
              <Button
                variant="ghost" size="icon"
                className="size-7 shrink-0 text-muted-foreground hover:text-destructive"
                aria-label={`Remove ${spec.label}`}
                onClick={() => onChange(links.filter((l) => l.id !== link.id))}
              >
                <XIcon className="size-3.5" />
              </Button>
            </div>

            <Input
              value={link.url}
              placeholder={spec.placeholder}
              className="mt-2 h-8 text-xs"
              onChange={(e) => update(link.id, { url: e.target.value })}
            />

            {isCustom && (
              <div className="mt-2 space-y-2 border-t border-border/60 pt-2">
                <Field>
                  <FieldLabel className="text-xs">Icon image</FieldLabel>
                  <ImageUploadInput
                    value={link.iconSrc ?? ""}
                    placeholder="https://yoursite.com/icon.png"
                    onChange={(iconSrc) => update(link.id, { iconSrc: iconSrc || undefined })}
                  />
                  <FieldDescription>
                    Square works best — it renders in a 32px box. Falls back to
                    a plain link icon until you add one.
                  </FieldDescription>
                </Field>
                <Field>
                  <FieldLabel className="text-xs">Label</FieldLabel>
                  <Input
                    value={link.label ?? ""}
                    placeholder="Our shop"
                    className="h-8 text-xs"
                    onChange={(e) => update(link.id, { label: e.target.value || undefined })}
                  />
                  <FieldDescription>
                    Alt text, and what shows if images are blocked.
                  </FieldDescription>
                </Field>
              </div>
            )}
          </div>
        );
      })}

      <Button variant="outline" size="sm" className="w-full" onClick={add}>
        <PlusIcon className="size-3.5" />
        Add link
      </Button>

      {links.length > 0 && (
        <Field>
          <FieldLabel className="text-xs text-muted-foreground">Preview</FieldLabel>
          <div className="flex flex-wrap items-center gap-1.5 rounded-lg border border-border/60 bg-muted/30 p-2.5">
            {links.map((link) => (
              // eslint-disable-next-line @next/next/no-img-element -- see PlatformIcon
              <img
                key={link.id}
                src={socialIconSrc(link)}
                alt=""
                className={cn("size-6 rounded-full object-cover", !link.url.trim() && "opacity-40")}
              />
            ))}
          </div>
        </Field>
      )}
    </>
  );
}

"use client";

import * as React from "react";
import CodeMirror from "@uiw/react-codemirror";
import { html as htmlLang } from "@codemirror/lang-html";
import { EditorView } from "@codemirror/view";
import { AlertTriangleIcon } from "lucide-react";

import { normalizeRawHtml } from "@/lib/email/normalize-raw-html";
import { cn } from "@/lib/utils";

/**
 * HTML editor for the rawHtml block.
 *
 * Normalizing runs on blur rather than on every keystroke — rewriting markup
 * while someone is halfway through typing a tag fights the user and moves the
 * caret. `text` is derived here so the plain-text half of the email stays in
 * sync without asking anyone to write it twice.
 */
export function HtmlCodeField({
  value,
  onCommit,
  minHeight = 220,
}: {
  value: string;
  /** Called with normalized markup plus its derived plain-text equivalent. */
  onCommit: (next: { html: string; text: string }) => void;
  minHeight?: number;
}) {
  const [draft, setDraft] = React.useState(value);
  const [warnings, setWarnings] = React.useState<string[]>([]);

  // Adopt outside edits (agent writes, undo) unless the user is mid-edit.
  const dirty = React.useRef(false);
  React.useEffect(() => {
    if (!dirty.current) setDraft(value);
  }, [value]);

  const commit = React.useCallback(() => {
    dirty.current = false;
    const result = normalizeRawHtml(draft);
    setWarnings(result.warnings);
    // Only rewrite the buffer when normalizing actually changed something,
    // so a clean paste doesn't reformat under the cursor.
    if (result.html !== draft) setDraft(result.html);
    onCommit({ html: result.html, text: result.text });
  }, [draft, onCommit]);

  const theme = React.useMemo(
    () =>
      EditorView.theme({
        "&": { fontSize: "12px", backgroundColor: "transparent" },
        "&.cm-focused": { outline: "none" },
        ".cm-content": { fontFamily: "var(--font-mono, ui-monospace, monospace)" },
        ".cm-gutters": { backgroundColor: "transparent", border: "none" },
      }),
    [],
  );

  return (
    <div className="flex flex-col gap-2">
      <div
        className={cn(
          "overflow-hidden rounded-md border border-border bg-muted/30",
          "focus-within:border-ring focus-within:ring-[3px] focus-within:ring-ring/50",
        )}
      >
        <CodeMirror
          value={draft}
          height={`${minHeight}px`}
          extensions={[htmlLang(), EditorView.lineWrapping, theme]}
          basicSetup={{ foldGutter: false, highlightActiveLine: false }}
          onChange={(next) => {
            dirty.current = true;
            setDraft(next);
          }}
          onBlur={commit}
        />
      </div>

      {warnings.length > 0 && (
        <ul className="flex flex-col gap-1.5 rounded-md border border-amber-500/30 bg-amber-500/5 p-2.5">
          {warnings.map((warning) => (
            <li key={warning} className="flex gap-1.5 text-xs text-amber-700 dark:text-amber-500">
              <AlertTriangleIcon className="mt-px size-3 shrink-0" />
              <span>{warning}</span>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}
